const palette={mint:'#afd8c8',lemon:'#e4ee50',magenta:'#970776',ochre:'#ce873b',green:'#7bc878',cyan:'#087f91',red:'#b52e36',yellow:'#efb539',blue:'#4f48cf'};if(palette[style])return palette[style];
