function finish(win,reason){if(state!=='play')return;if(typeof editorTesting!=='undefined'&&editorTesting){editorRunResult(win,reason);return;}state=win?'win':'dead';let bonus=0,newTimeBest=false;if(win&&mode==='story'&&Number.isFinite(time)&&time>0){const previous=data.storyTimes[level];newTimeBest=!previous||time<previous.best;if(newTimeBest)data.storyTimes[level]={best:time};}if(mode==='story'&&win){if(!data.cleared.includes(level)){data.cleared.push(level);bonus=20;data.coins+=bonus}data.unlocked=Math.max(data.unlocked,Math.min(STORY_VISIBLE_COUNT-1,level+1))}if(mode==='endless')data.best=Math.max(data.best,Math.floor(z));save();beep(win?900:80,.4,win?'sine':'sawtooth');$('levels').innerHTML='';$('shopgrid').innerHTML='';$('overlay').classList.remove('hidden');$('start').classList.remove('hidden');$('home').classList.remove('hidden');$('eyebrow').textContent=win?'COURSE COMPLETE':'SIGNAL LOST';$('title').textContent=win?'항로 확보.':'다시, 도전.';$('description').textContent=win?'코스 '+(Math.floor(level/3)+1)+'-'+(level%3+1)+' 클리어 · '+runCoins+' 코인'+(bonus?' + 첫 클리어 20 코인':'')+'. '+(level<STORY_VISIBLE_COUNT-1?'다음 코스를 선택해 계속 도전하세요.':'현재 스토리 7-3까지 완주했습니다!'):reason+' · '+Math.floor(z)+'m · 획득 '+runCoins+' 코인. 모은 코인은 유지됩니다.';if(win&&mode==='story'&&data.storyTimes[level])$('description').textContent+='\n이번 '+formatClearTime(time)+' · 최단 '+formatClearTime(data.storyTimes[level].best)+(newTimeBest?' · 신기록!':'');wallet();$('start').textContent=win&&mode==='story'&&level<STORY_VISIBLE_COUNT-1?'다음 코스 바로 시작 →':'다시 도전 →';if(typeof showRevenueResult==="function")showRevenueResult(win)}
