start=beginRun;


const preparedRun=beginRun;
beginRun=function(startMovingForTest=false){preparedRun();if(startMovingForTest)return;speed=0;throttle=0;state='ready';$('note').textContent='정지 상태 · 오른쪽 속도 레버를 올리면 출발합니다';};
start=beginRun;
function launchFromRest(){if(state!=='ready')return;state='play';throttle=6;$('note').textContent='출발 · 속도 레버 또는 ↑/↓로 조절';}
const movingStep=step;step=function(dt){if(state==='ready'){if(keys.ArrowUp)launchFromRest();return}movingStep(dt)};
showMenu('story');buildTrack();requestAnimationFrame(loop);

