function editorRunResult(win,reason){state=win?'win':'dead';clearTimeout(nextTimer);nextTimer=0;$('overlay').classList.remove('hidden');$('levels').innerHTML='';$('shopgrid').innerHTML='';$('revenue').innerHTML='';$('eyebrow').textContent='EDITOR TEST';$('title').textContent=win?'시험 주행 완료.':'시험 주행 종료.';$('description').textContent=(win?'맵 끝에 도착했습니다.':reason+' · '+Math.floor(z)+'m')+' 편집으로 돌아가 수정할 수 있습니다.';$('start').classList.remove('hidden');$('start').textContent='편집으로 돌아가기';$('home').classList.add('hidden')}
