 const cooldown={coin:.065,fuel:.2,jump:.12,landing:.12,ui:.07,crash:.8,fall:.8,complete:1,warning:4}[name]||.1;
 if(c.currentTime-(flightAudio.last[name]??-Infinity)<cooldown)return;flightAudio.last[name]=c.currentTime;
