// Startup owns the reveal; the old menu stays hidden until a complete first frame.
const launch={phase:'logo',progress:0,build:typeof document.currentScript?.src==='string'?document.currentScript.src.match(/starway-([a-f0-9]+)\.js/)?.[1]:null};
if(typeof window!=='undefined')window.starwayLaunchPhase='logo';
function launchProgress(value,message){launch.progress=value;$('bootFill').style.width=value+'%';$('bootTrack').setAttribute('aria-valuenow',String(value));$('bootMessage').textContent=message;}
function launchReveal(){if(launch.phase==='done')return;launch.phase='done';if(typeof window!=='undefined')window.starwayLaunchPhase='done';draw();document.documentElement.classList.remove('booting');updateMusic();}
async function launchVersion(){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),4000);
 try{const response=await fetch('./version.json',{cache:'no-store',credentials:'same-origin',signal:controller.signal});if(!response.ok)throw Error('version');const latest=await response.json();if(!latest.build||!launch.build)throw Error('version');return latest.build===launch.build?'current':'changed';}catch{return 'offline';}finally{clearTimeout(timer);}
}
async function launchLoading(){
 launch.phase='loading';if(typeof window!=='undefined')window.starwayLaunchPhase='loading';$('bootScreen').classList.add('loading');
 $('bootAudio').textContent=sound?'음악 ON · 화면을 눌러 재생':'음악 켜기';
 $('bootAudio').onclick=()=>{settings.sound=true;sound=true;settings.bgm=true;applySettings();persistSettings();unlockMusic();$('bootAudio').textContent='음악 ON';};
 prepareLaunchMusic();launchProgress(20,'화면·그래픽 준비 중');
 try{
  draw();await new Promise(resolve=>requestAnimationFrame(resolve));
  launchProgress(50,'글꼴·인터페이스 준비 중');
  if(document.fonts?.ready)await Promise.race([document.fonts.ready,new Promise(resolve=>setTimeout(resolve,2000))]);
  launchProgress(75,'최신 버전 확인 중');const version=await launchVersion();
  launchProgress(100,version==='current'?'최신 버전 · 준비 완료':version==='changed'?'새 버전이 있습니다. 새로고침하면 적용됩니다.':'버전 확인 불가 · 현재 버전으로 시작할 수 있습니다.');
  if(version==='changed'){$('bootContinue').style.display='inline-block';$('bootContinue').textContent='최신 버전 불러오기';$('bootContinue').onclick=()=>location.reload();}
  else setTimeout(launchReveal,version==='offline'?1300:500);
 }catch{launchProgress(100,'준비를 마치지 못했습니다. 다시 시도해 주세요.');$('bootContinue').style.display='inline-block';$('bootContinue').textContent='다시 불러오기';$('bootContinue').onclick=()=>location.reload();}
}
function prepareLaunchMusic(){
 if(!sound||!settings.bgm)return;
 const c=flightAudioReady();if(!c)return;
 loadMusic('menu');
 if(c.state==='suspended')Promise.resolve(c.resume()).then(()=>updateMusic()).catch(()=>{});
 updateMusic();
}
function startLaunch(){
 // One-time upgrade from the old silent-by-default startup. Subsequent mute choices persist.
 if(!settings.launchAudioV2){settings.launchAudioV2=true;settings.sound=true;settings.bgm=true;sound=true;applySettings();persistSettings();}
 prepareLaunchMusic();setTimeout(launchLoading,2000);
}

;
// Local release UI gate only. No persistent unlock and no server-authentication claim.
let developerModeEnabled=false;
function syncDeveloperMode(){
 $('overlay').setAttribute('data-developer-mode',developerModeEnabled?'on':'off');
 $('developerModeToggle').textContent=developerModeEnabled?'개발자모드 끄기':'개발자모드 켜기';
 $('developerModeToggle').setAttribute('aria-pressed',String(developerModeEnabled));
}
const developerMenu=showMenu;showMenu=function(...args){const result=developerMenu(...args);$('developerPasswordPanel').classList.add('hidden');$('developerPassword').value='';$('developerModeStatus').textContent='';syncDeveloperMode();return result;};
const developerEditorClick=$('editorOpen').onclick;$('editorOpen').onclick=()=>{if(developerModeEnabled)developerEditorClick();};
$('developerModeToggle').onclick=()=>{
 if(developerModeEnabled){developerModeEnabled=false;$('developerPasswordPanel').classList.add('hidden');$('developerPassword').value='';$('developerModeStatus').textContent='개발자 모드를 껐습니다. 시작 메뉴의 맵 에디터를 숨깁니다.';syncDeveloperMode();return;}
 $('developerPasswordPanel').classList.remove('hidden');$('developerPassword').value='';$('developerModeStatus').textContent='개발자 비밀번호를 입력하세요.';$('developerPassword').focus?.();
};
function unlockDeveloperMode(){
 if($('developerPassword').value!=='ODDLEAF2026!'){$('developerModeStatus').textContent='비밀번호가 올바르지 않습니다.';$('developerPassword').value='';return;}
 developerModeEnabled=true;$('developerPassword').value='';$('developerPasswordPanel').classList.add('hidden');$('developerModeStatus').textContent='개발자 모드가 켜졌습니다. 시작 메뉴에 맵 에디터가 표시됩니다.';syncDeveloperMode();
}
$('developerPasswordConfirm').onclick=unlockDeveloperMode;
$('developerPassword').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();unlockDeveloperMode();}});
$('developerPasswordCancel').onclick=()=>{$('developerPasswordPanel').classList.add('hidden');$('developerPassword').value='';$('developerModeStatus').textContent='';};
syncDeveloperMode();

;draw();startLaunch();
